// local patch 2026-09-08 IRIS: zero-spend quota refresh for idle Codex accounts.
// This is the GET endpoint used by OpenAI's own backend-client. Never consume
// reset credits, run a model, or infer a window duration from its position.
export function normalizeCodexUsage(data) {
  const limit = data?.rate_limit;
  const result = { fiveHour: null, sevenDay: null };
  for (const window of [limit?.primary_window, limit?.secondary_window]) {
    if (!window) continue;
    const pct = window.used_percent;
    const seconds = window.limit_window_seconds;
    if (typeof pct !== 'number' || !Number.isFinite(pct) || pct < 0
        || typeof seconds !== 'number' || !Number.isFinite(seconds) || seconds <= 0) continue;
    const key = near(seconds / 60, FIVE_HOUR_MINUTES) ? 'fiveHour'
      : near(seconds / 60, SEVEN_DAY_MINUTES) ? 'sevenDay' : null;
    if (!key) continue;
    result[key] = { utilization: pct / 100,
      resetAt: typeof window.reset_at === 'number' && Number.isFinite(window.reset_at) && window.reset_at > 0
        ? window.reset_at * 1000 : null };
  }
  if (!result.fiveHour && !result.sevenDay) return { error: 'Unrecognized Codex usage payload' };
  if (typeof data.plan_type === 'string') result.planType = data.plan_type;
  if (typeof limit.allowed === 'boolean') result.allowed = limit.allowed;
  return result;
}

export async function fetchCodexUsage(accessToken, accountId, { signal } = {}) {
  if (!accessToken || !accountId) return { error: 'Codex account credential or identity missing' };
  try {
    const res = await proxyFetch('https://chatgpt.com/backend-api/wham/usage', {
      method: 'GET', redirect: 'error', signal,
      headers: { Authorization: `Bearer ${accessToken}`, 'ChatGPT-Account-Id': accountId,
        Accept: 'application/json', 'User-Agent': 'codex-cli' },
    });
    // Do not copy server bodies (which can contain account data) into status.
    if (!res.ok) return { error: `Codex usage HTTP ${res.status}`, status: res.status };
    const data = await res.json();
    if (data.account_id && data.account_id !== accountId) return { error: 'Codex usage account identity mismatch' };
    return normalizeCodexUsage(data);
  } catch (err) {
    return { error: err.name === 'AbortError' ? 'Codex usage timed out' : 'Codex usage request failed' };
  }
}

