import { randomUUID } from 'node:crypto';
import { providerForPath } from './provider.js';
import { safeLine } from './safe-text.js';

const MAX_ACTIVE = 256;
const MAX_RECENT = 100;
const ACTIVITY_HOOKS = ['onRequestStart', 'onRequestModel', 'onRequestRouted', 'onRequestEnd'];

function requestPath(value) {
  return String(value || '').split(/[?#]/)[0].replace(/^\/tc-acct\/[^/]+(?=\/)/, '');
}

function publicPath(value) {
  const path = requestPath(value);
  // Publish only known API endpoint names. Arbitrary path segments can contain
  // private data just as query strings can; neither belongs in a status view.
  const known = /^\/(?:v1\/(?:messages(?:\/count_tokens)?|models|complete)|backend-api\/codex\/(?:responses(?:\/compact)?|models)|api\/event_logging(?:\/batch)?)$/;
  return known.test(path) ? safeLine(path, 240) : '(other)';
}

function text(value, max = 120) {
  return value == null ? null : safeLine(value, max);
}

/** Ephemeral, bounded request metadata. Credentials, prompts, responses,
 * session ids and client/dimension headers never enter this object. */
export class ActivityTracker {
  constructor({ now = Date.now } = {}) {
    this.instanceId = randomUUID();
    this.now = now;
    this.active = new Map();
    this.recent = [];
    this.lastRoutedAccounts = {};
    this.droppedActive = 0;
  }

  onRequestStart(id, info = {}) {
    if (!this.active.has(id) && this.active.size >= MAX_ACTIVE) {
      // The display must stay bounded even if many connections are held open.
      // Eviction affects observation only; it never cancels or delays a call.
      this.active.delete(this.active.keys().next().value);
      this.droppedActive++;
    }
    this.active.set(id, {
      id,
      provider: providerForPath(requestPath(info.path)),
      method: text(info.method, 16),
      path: publicPath(info.path),
      account: null,
      model: null,
      effort: null,
      pinned: !!info.pinned,
      startedAt: new Date(this.now()).toISOString(),
      endedAt: null,
      durationMs: null,
      status: null,
    });
  }

  onRequestModel(id, info = {}) {
    const row = this.active.get(id);
    if (row && info.model) row.model = text(info.model);
    if (row && info.effort) row.effort = text(info.effort, 24); // (local patch 2026-09-07 IRIS)
  }

  onRequestRouted(id, info = {}) {
    const row = this.active.get(id);
    const provider = info.provider === 'codex' || info.provider === 'anthropic' ? info.provider : row?.provider;
    const account = text(info.account);
    if (row) {
      row.account = account;
      if (provider) row.provider = provider;
    }
    // A routed event can outlive an evicted active row, or belong to hidden
    // telemetry. Provider metadata still identifies the actual selected pool.
    if (provider && account) this.lastRoutedAccounts[provider] = account;
  }

  onRequestEnd(id, info = {}) {
    const row = this.active.get(id);
    this.active.delete(id);
    if (this.recent.some(r => r.id === id)) return;
    const ended = this.now();
    const started = row?.startedAt ? Date.parse(row.startedAt) : null;
    this.recent.unshift({
      id,
      provider: row?.provider || providerForPath(requestPath(info.path)),
      method: text(info.method, 16) || row?.method || null,
      path: info.path == null ? (row?.path || '(other)') : publicPath(info.path),
      account: text(info.account) || row?.account || null,
      model: text(info.model) || row?.model || null,
      effort: row?.effort || null,
      pinned: info.pinned == null ? !!row?.pinned : !!info.pinned,
      startedAt: row?.startedAt || null,
      endedAt: new Date(ended).toISOString(),
      durationMs: started == null ? null : Math.max(0, ended - started),
      status: Number.isFinite(info.status) ? info.status : null,
    });
    if (this.recent.length > MAX_RECENT) this.recent.length = MAX_RECENT;
  }

  snapshot() {
    return {
      instanceId: this.instanceId,
      active: [...this.active.values()].map(row => ({ ...row })),
      recent: this.recent.map(row => ({ ...row })),
      lastRoutedAccounts: { ...this.lastRoutedAccounts },
      droppedActive: this.droppedActive,
    };
  }
}

/** Add metadata observation without replacing existing TUI/file-log hooks. */
export function withActivityHooks(hooks, tracker) {
  const combined = { ...hooks };
  for (const name of ACTIVITY_HOOKS) {
    const previous = hooks[name];
    combined[name] = function (id, info) {
      // Monitoring is never allowed to fail inference, nor to suppress an
      // existing hook. Preserve the existing callback's result and errors.
      try { tracker[name](id, info); } catch { /* observation only */ }
      return previous?.call(this, id, info);
    };
  }
  return combined;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { once } from 'node:events';
import { createAttachSession } from './src/tui-remote.js';
import { createProxyRequestListener } from './src/server.js';
import { AccountManager } from './src/account-manager.js';

const startedAt = '2026-09-07T04:00:00.000Z';
const endedAt = '2026-09-07T04:00:02.000Z';
const accounts = [
  { name: 'claude-internal', displayName: 'same@example.test', type: 'oauth', provider: 'anthropic', quota: {} },
  { name: 'codex-internal', displayName: 'same@example.test', type: 'oauth', provider: 'codex', quota: {} },
];
const row = (id, provider = 'codex') => ({
  id, provider, account: provider === 'codex' ? 'codex-internal' : 'claude-internal',
  model: provider === 'codex' ? 'gpt-test' : 'claude-test', method: 'POST',
  path: provider === 'codex' ? '/backend-api/codex/responses' : '/v1/messages',
  startedAt, endedAt, durationMs: 2000, status: 200,
});
function sessionFor(activity) {
  let next = { accounts, currentAccount: 'codex-internal', activity };
  const control = { status: async () => { if (next instanceof Error) throw next; return next; } };
  const session = createAttachSession({ control, config: { proxy: { port: 3456 }, sessionTitles: { enabled: false } } });
  return { ...session, set: value => { next = value; } };
}

test('attach displays concurrent requests with distinct provider names', async () => {
  const s = sessionFor({ instanceId: 'server-1', active: [row(1, 'anthropic'), row(2)], recent: [], lastRoutedAccounts: { anthropic: 'claude-internal', codex: 'codex-internal' } });
  await s.poll();
  assert.equal(s.tui.active.size, 2);
  assert.equal(s.tui.remoteActivityAvailable, true);
  const labels = [...s.tui.active.values()].map(r => r.account);
  assert.ok(labels.some(a => a.includes('Claude') && a.includes('same@example.test')));
  assert.ok(labels.some(a => a.includes('Codex') && a.includes('same@example.test')));
  assert.deepEqual(s.am.lastRoutedAccounts, { anthropic: 'claude-internal', codex: 'codex-internal' });
  assert.equal([...s.tui.active.values()][0].started, Date.parse(startedAt));
});

test('attach catches fast completions exactly once and preserves their time and duration', async () => {
  const s = sessionFor({ instanceId: 'server-1', active: [], recent: [row(3)], lastRoutedAccounts: {} });
  await s.poll();
  assert.equal(s.tui.log.length, 1);
  assert.match(s.tui.log[0].msg, /Codex.*same@example\.test/);
  assert.match(s.tui.log[0].msg, /200, 2\.0s/);
  const expectedTime = new Date(endedAt).toLocaleTimeString('en-US', { hour12: false });
  assert.equal(s.tui.log[0].t, expectedTime);
  await s.poll();
  assert.equal(s.tui.log.length, 1);
  assert.equal(s.tui.active.size, 0);
});

test('attach clears stale active rows on disconnect and server restart permits reused ids', async () => {
  const s = sessionFor({ instanceId: 'server-1', active: [row(9)], recent: [row(1)], lastRoutedAccounts: {} });
  await s.poll();
  assert.equal(s.tui.active.size, 1);
  s.set(new Error('offline'));
  await s.poll();
  assert.equal(s.tui.active.size, 0);
  assert.equal(s.am.connected, false);
  s.set({ accounts, activity: { instanceId: 'server-2', active: [], recent: [row(1)], lastRoutedAccounts: {} } });
  await s.poll();
  assert.equal(s.tui.active.size, 0);
  assert.equal(s.tui.log.filter(r => r.msg.includes('gpt-test')).length, 2);
});

test('attach accepts old servers without activity and retains action messages', async () => {
  const s = sessionFor({ instanceId: 'server-1', active: [row(1)], recent: [], lastRoutedAccounts: { codex: 'codex-internal' } });
  await s.poll();
  s.tui._addLog('local action');
  s.set({ accounts, currentAccount: 'codex-internal' });
  await s.poll();
  assert.equal(s.tui.active.size, 0);
  assert.equal(s.tui.remoteActivityAvailable, false);
  assert.equal(s.am.lastRoutedAccounts, undefined);
  assert.ok(s.tui.log.some(r => r.msg === 'local action'));
});

test('attach does not invent elapsed time when a bounded server has no request start', async () => {
  const entry = { ...row(4), startedAt: null, durationMs: null };
  const s = sessionFor({ instanceId: 'server-1', active: [], recent: [entry], lastRoutedAccounts: {} });
  await s.poll();
  assert.equal(s.tui.log.length, 1);
  assert.match(s.tui.log[0].msg, /200, \?s/);
});

test('completions in the same millisecond retain the server completion order', async () => {
  const entries = [3, 2, 1].map(id => ({ ...row(id), model: `model-${id}` }));
  const s = sessionFor({ instanceId: 'server-1', active: [], recent: entries, lastRoutedAccounts: {} });
  await s.poll();
  assert.match(s.tui.log[0].msg, /model-3/);
  assert.match(s.tui.log[2].msg, /model-1/);
});

test('independent proxy listeners never reuse activity request ids', async t => {
  const ids = [];
  const am = new AccountManager([]);
  const make = async () => {
    const handler = createProxyRequestListener({ accountManager: am, upstream: 'http://127.0.0.1:1', config: {}, hooks: { onRequestEnd: id => ids.push(id) } });
    const server = http.createServer(handler);
    server.listen(0, '127.0.0.1');
    await once(server, 'listening');
    t.after(() => { server.closeAllConnections(); server.close(); });
    return server.address().port;
  };
  const p1 = await make();
  const p2 = await make();
  const r1 = await fetch(`http://127.0.0.1:${p1}/tc-acct/missing/v1/messages`);
  const r2 = await fetch(`http://127.0.0.1:${p2}/tc-acct/missing/v1/messages`);
  assert.equal(r1.status, 404);
  assert.equal(r2.status, 404);
  assert.equal(ids.length, 2);
  assert.equal(new Set(ids).size, 2);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { ActivityTracker, withActivityHooks } from './src/activity.js';

test('activity shows in-flight model and actual routed provider without secrets', () => {
  let time = 1000;
  const tracker = new ActivityTracker({ now: () => time });
  tracker.onRequestStart(1, {
    method: 'POST', path: '/backend-api/codex/responses?access_token=SECRET',
    body: 'PROMPT', headers: { authorization: 'SECRET' }, sessionId: 'SESSION', client: 'CLIENT', dimensions: { private: 'DIMENSION' },
  });
  tracker.onRequestModel(1, { model: 'gpt-test\n\u001b[2J' });
  tracker.onRequestRouted(1, { account: 'internal-codex', provider: 'codex' });
  const status = tracker.snapshot();
  assert.equal(status.active.length, 1);
  assert.equal(status.active[0].path, '/backend-api/codex/responses');
  assert.equal(status.active[0].model, 'gpt-test');
  assert.equal(status.active[0].account, 'internal-codex');
  assert.equal(status.lastRoutedAccounts.codex, 'internal-codex');
  assert.equal(status.lastRoutedAccounts.anthropic, undefined);
  assert.doesNotMatch(JSON.stringify(status), /SECRET|PROMPT|SESSION|CLIENT|DIMENSION/);
  status.active[0].account = 'outside mutation';
  status.lastRoutedAccounts.codex = 'outside mutation';
  assert.equal(tracker.snapshot().active[0].account, 'internal-codex');
  assert.equal(tracker.snapshot().lastRoutedAccounts.codex, 'internal-codex');
  time = 3500;
  tracker.onRequestEnd(1, { method: 'POST', path: '/backend-api/codex/responses?key=SECRET', status: 200, account: 'internal-codex', model: 'gpt-test' });
  const done = tracker.snapshot();
  assert.equal(done.active.length, 0);
  assert.equal(done.recent[0].durationMs, 2500);
  assert.equal(done.recent[0].startedAt, '1970-01-01T00:00:01.000Z');
  assert.equal(done.recent[0].endedAt, '1970-01-01T00:00:03.500Z');
  assert.doesNotMatch(JSON.stringify(done), /SECRET/);
});

test('pinned retry updates last routed identity without changing request identity', () => {
  const tracker = new ActivityTracker();
  tracker.onRequestStart(1, { method: 'POST', path: '/v1/messages', pinned: true });
  tracker.onRequestRouted(1, { account: 'claude-1', provider: 'anthropic' });
  tracker.onRequestRouted(1, { account: 'claude-2', provider: 'anthropic' });
  const s = tracker.snapshot();
  assert.equal(s.active.length, 1);
  assert.equal(s.active[0].account, 'claude-2');
  assert.equal(s.active[0].pinned, true);
  assert.deepEqual(s.lastRoutedAccounts, { anthropic: 'claude-2' });
});

test('active and completed history stay bounded during long sessions', () => {
  const tracker = new ActivityTracker();
  for (let id = 1; id <= 300; id++) tracker.onRequestStart(id, { method: 'POST', path: '/v1/messages' });
  assert.equal(tracker.snapshot().active.length, 256);
  for (let id = 1; id <= 300; id++) tracker.onRequestEnd(id, { method: 'POST', path: '/v1/messages', status: 499 });
  const s = tracker.snapshot();
  assert.equal(s.active.length, 0);
  assert.equal(s.recent.length, 100);
  assert.equal(s.recent[0].id, 300);
  assert.equal(s.recent.at(-1).id, 201);
});

test('an early error without a start has unknown duration and no arbitrary URL data', () => {
  const tracker = new ActivityTracker();
  tracker.onRequestEnd(2, { method: 'GET', path: '/private/URLSECRET?key=QUERYSECRET', account: 'missing', status: 404 });
  const r = tracker.snapshot().recent[0];
  assert.equal(r.status, 404);
  assert.equal(r.startedAt, null);
  assert.equal(r.durationMs, null);
  assert.doesNotMatch(JSON.stringify(r), /URLSECRET|QUERYSECRET/);
});

test('activity recorder failures never break existing hooks or their return values', () => {
  const tracker = new ActivityTracker();
  tracker.onRequestStart = () => { throw new Error('tracker failed'); };
  let called = false;
  const hooks = withActivityHooks({ onRequestStart: () => { called = true; return 'prior result'; } }, tracker);
  assert.equal(hooks.onRequestStart(1, { method: 'POST', path: '/v1/messages' }), 'prior result');
  assert.equal(called, true);
  assert.doesNotThrow(() => hooks.onRequestEnd(1, { status: 502 }));
});

test('activity recording retains an existing callback error rather than swallowing it', () => {
  const tracker = new ActivityTracker();
  const failure = new Error('existing hook error');
  const hooks = withActivityHooks({ onRequestStart: () => { throw failure; } }, tracker);
  assert.throws(() => hooks.onRequestStart(1, { path: '/v1/messages' }), err => err === failure);
  assert.equal(tracker.snapshot().active.length, 1);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { AccountManager } from './src/account-manager.js';
import { syncAccountsFromDisk } from './src/sync-accounts.js';
import { TUI, displayWidth } from './src/tui.js';

const plain = value => value.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '');
const fixtures = () => [
  { id: 'fixture-claude', name: 'claude-internal', displayName: 'same@example.invalid', type: 'oauth', accessToken: 'fake-claude', refreshToken: 'fake-refresh-claude' },
  { id: 'fixture-codex1', name: 'codex-1', displayName: 'same@example.invalid', provider: 'codex', type: 'oauth', accessToken: 'fake-codex1', refreshToken: 'fake-refresh-codex1' },
  { id: 'fixture-codex2', name: 'codex-2', displayName: 'a-longer-email-address@example.invalid', provider: 'codex', type: 'oauth', accessToken: 'fake-codex2', refreshToken: 'fake-refresh-codex2' },
];
function makeView(accounts = fixtures(), options = {}) {
  const am = new AccountManager(accounts);
  const tui = new TUI({ accountManager: am, config: { proxy: { port: 3456 }, accounts }, ...options });
  return { am, tui };
}
function row(tui, index, nameWidth = 42) {
  return plain(tui._renderAcct(index, 8, true, [], [], {}, false, nameWidth));
}
function frame(tui, width = 160, height = 24) {
  const columns = Object.getOwnPropertyDescriptor(process.stdout, 'columns');
  const rows = Object.getOwnPropertyDescriptor(process.stdout, 'rows');
  let output = '';
  const paint = tui._paint;
  try {
    Object.defineProperty(process.stdout, 'columns', { configurable: true, value: width });
    Object.defineProperty(process.stdout, 'rows', { configurable: true, value: height });
    // Capture the real renderer at its terminal output boundary.
    tui._paint = value => { output = value; };
    tui._render();
  } finally {
    tui._paint = paint;
    if (columns) Object.defineProperty(process.stdout, 'columns', columns); else delete process.stdout.columns;
    if (rows) Object.defineProperty(process.stdout, 'rows', rows); else delete process.stdout.rows;
  }
  return plain(output);
}

test('status exposes service and display email without changing account identity or selection', () => {
  const { am } = makeView();
  const status = am.getStatus();
  assert.deepEqual(status.accounts.map(a => ({ name: a.name, displayName: a.displayName, provider: a.provider })), [
    { name: 'claude-internal', displayName: 'same@example.invalid', provider: 'anthropic' },
    { name: 'codex-1', displayName: 'same@example.invalid', provider: 'codex' },
    { name: 'codex-2', displayName: 'a-longer-email-address@example.invalid', provider: 'codex' },
  ]);
  assert.equal(status.currentAccount, 'claude-internal');
  assert.equal(am.currentIndex, 0);
  assert.equal(am.providerCursors.size, 0);
  assert.equal(new Set(am.accounts.map(a => a.id)).size, 3);
});

test('reload updates and removes display names while retaining the three internal accounts', async () => {
  const mem = { accounts: fixtures() };
  const am = new AccountManager(mem.accounts);
  const disk = structuredClone(mem);
  disk.accounts[1].displayName = 'updated@example.invalid';
  await syncAccountsFromDisk(disk, mem, am);
  assert.equal(am.getStatus().accounts[1].displayName, 'updated@example.invalid');
  assert.equal(mem.accounts[1].displayName, 'updated@example.invalid');
  assert.equal(am.accounts[1].name, 'codex-1');
  assert.equal(am.accounts.length, 3);
  delete disk.accounts[1].displayName;
  await syncAccountsFromDisk(disk, mem, am);
  assert.equal(am.getStatus().accounts[1].displayName, 'codex-1');
  assert.equal(Object.hasOwn(mem.accounts[1], 'displayName'), false);
});

test('account rows display matching emails with distinct service labels', () => {
  const { tui } = makeView();
  assert.match(row(tui, 0), /same@example\.invalid\s+Claude\s+active/);
  assert.match(row(tui, 1), /same@example\.invalid\s+Codex\s+active/);
  assert.doesNotMatch(row(tui, 1), /codex-1/);
});

test('last-routed arrows mark one account per service independently of currentIndex', () => {
  const { am, tui } = makeView();
  am.currentIndex = 0;
  am.lastRoutedAccounts = { anthropic: 'claude-internal', codex: 'codex-2' };
  assert.equal(row(tui, 0).includes('►'), true);
  assert.equal(row(tui, 1).includes('►'), false);
  assert.equal(row(tui, 2).includes('►'), true);
  am.lastRoutedAccounts.codex = 'codex-1';
  assert.equal(row(tui, 0).includes('►'), true);
  assert.equal(row(tui, 1).includes('►'), true);
  assert.equal(row(tui, 2).includes('►'), false);
  assert.equal(am.currentIndex, 0);
});

test('new empty activity history shows no routed arrow before the first request', () => {
  const { am, tui } = makeView();
  am.lastRoutedAccounts = {};
  assert.equal(row(tui, 0).includes('►'), false);
  assert.equal(row(tui, 1).includes('►'), false);
});

test('older server snapshots retain the legacy current-account marker', () => {
  const { am, tui } = makeView();
  assert.equal(am.lastRoutedAccounts, undefined);
  am.currentIndex = 1;
  assert.equal(row(tui, 0).includes('►'), false);
  assert.equal(row(tui, 1).includes('►'), true);
});

test('full frame budgets name width from displayed emails and explains routed markers', () => {
  const { am, tui } = makeView();
  am.lastRoutedAccounts = {};
  const output = frame(tui);
  assert.match(output, /a-longer-email-address@example\.invalid/);
  assert.match(output, /► Last routed per service/);
  const accountRows = output.split('\r\n').filter(line => /@example\.invalid/.test(line));
  assert.equal(accountRows.length, 3);
  assert.ok(accountRows.every(line => displayWidth(line) <= 160));
  for (const width of [50, 80]) {
    assert.ok(frame(tui, width).split('\r\n').every(line => displayWidth(line) <= width));
  }
});

test('attached request history uses Activity while unsupported older servers keep Messages', () => {
  const { tui } = makeView(fixtures(), { remote: true });
  assert.match(frame(tui), /Messages/);
  tui.remoteActivityAvailable = true;
  assert.match(frame(tui), /Activity/);
  assert.doesNotMatch(frame(tui), /Messages/);
});

