// local patch 2026-09-18 IRIS: name every provider host up front. server.js computes
// this list ONCE at start (mitmHostList) and memoises the leaf, but IRIS adds the
// Codex account AFTER the relay is up (install step 7), so a leaf minted from the
// accounts-at-start would never cover chatgpt.com until a restart -- and the
// installer never restarts a running relay. Naming the host costs nothing when no
// Codex account exists: hostMode() still tunnels it.
export function mitmHosts(config) {
  return [...new Set([upstreamHostOf(config), 'chatgpt.com', ...interceptHostsFor(config?.accounts || [])])];
