// (local patch 2026-10-02 IRIS) Refresh-token health.
//
// Incident 2026-10-02: four OAuth accounts' refresh tokens were rejected
// (invalid_grant) one by one over three days. Each was quietly marked 'error'
// and dropped from rotation, nothing told the operator, the log lines carried
// no time, and the client finally saw "all accounts are at their quota" --
// a quota diagnosis for what was really a re-login problem.
//
// This module is the observation + alert layer for that failure. It never
// sees or writes a token value: it records account names, times, the refresh
// token's expiry when upstream discloses one, and a short classified reason.
//
//   - stampConsole()      prefix every log line with local time (headless runs)
//   - noteRefreshResponseKeys()  log the token endpoint's FIELD NAMES once
//   - classifyRefreshError()     expired / invalid / rejected / server / network
//   - AuthHealth          per-account state, snapshot file, event log, alerts
//
// Files (siblings of the config, e.g. ~/.config/):
//   teamclaude.auth-health.json   latest snapshot, read by the dashboard/hooks
//   teamclaude.auth-events.jsonl  append-only history (rotated at 1 MB)
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';

const HOUR = 3_600_000;
const DAY = 24 * HOUR;

// ---------------------------------------------------------------- timestamps

function pad(n) { return String(n).padStart(2, '0'); }
export function stamp(d = new Date()) {
  return `${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

let stamped = false;
/**
 * Prefix console output with local time. Only when stdout is not a terminal
 * (the managed/headless server writes to log files); the interactive TUI keeps
 * its own layout. TEAMCLAUDE_LOG_TIME=1 forces it on, =0 off.
 */
export function stampConsole() {
  const flag = process.env.TEAMCLAUDE_LOG_TIME;
  if (stamped || flag === '0') return;
  if (process.stdout.isTTY && flag !== '1') return;
  stamped = true;
  for (const level of ['log', 'warn', 'error']) {
    const orig = console[level].bind(console);
    console[level] = (first, ...rest) => (typeof first === 'string'
      ? orig(`[${stamp()}] ${first}`, ...rest)
      : orig(first, ...rest));
  }
}

// ------------------------------------------------------------ classification

let sink = null;      // the running AuthHealth, if any
let keysNoted = false;

/** Log the token endpoint's response FIELD NAMES (never values), once per process. */
export function noteRefreshResponseKeys(data) {
  if (keysNoted || !data || typeof data !== 'object') return;
  keysNoted = true;
  const fields = Object.keys(data).sort();
  console.log(`[TeamClaude] Token refresh response fields: ${fields.join(', ')}`);
  sink?.event({ type: 'refresh-fields', fields });
}

/** Map a refresh failure to a small closed set of kinds. */
export function classifyRefreshError(err) {
  const msg = String(err?.message || '');
  const st = err?.status;
  if (st === 400 || st === 401 || st === 403) {
    if (/expired/i.test(msg)) return 'expired';
    if (/not found|invalid/i.test(msg)) return 'invalid';
    return 'rejected';
  }
  if (typeof st === 'number' && st >= 500) return 'server';
  if (typeof st === 'number') return `http-${st}`;
  return 'network';
}

/** Short, token-free reason: the error code/description from the body, or a scrubbed message. */
export function safeReason(err) {
  const msg = String(err?.message || '');
  const m = msg.match(/\{[\s\S]*\}/);
  if (m) {
    try {
      const j = JSON.parse(m[0]);
      const e = j.error;
      const code = typeof e === 'string' ? e : (e?.type || e?.code);
      const desc = j.error_description || e?.message;
      const out = [code, desc].filter(Boolean).join(': ');
      if (out) return out.slice(0, 160);
    } catch { /* fall through */ }
  }
  return msg.replace(/[A-Za-z0-9_\-.]{24,}/g, '[...]').slice(0, 160);
}

const KIND_KO = {
  expired: '로그인 열쇠 만료',
  invalid: '로그인 열쇠 무효 — 다른 곳에서 같은 계정 로그인 또는 갱신 중 끊김 가능',
  rejected: '인증 거절',
};

// ------------------------------------------------------------------- notify

function psQuote(s) { return `'${String(s).replace(/'/g, "''")}'`; }

/** Windows balloon via a hidden PowerShell. Fire-and-forget; never throws. */
export function windowsNotify(title, body) {
  if (process.platform !== 'win32' || process.env.TEAMCLAUDE_NOTIFY === '0') return false;
  const script = [
    'Add-Type -AssemblyName System.Windows.Forms',
    'Add-Type -AssemblyName System.Drawing',
    '$n = New-Object System.Windows.Forms.NotifyIcon',
    '$n.Icon = [System.Drawing.SystemIcons]::Warning',
    "$n.BalloonTipIcon = 'Warning'",
    `$n.BalloonTipTitle = ${psQuote(String(title).slice(0, 60))}`,
    `$n.BalloonTipText = ${psQuote(String(body).slice(0, 250))}`,
    '$n.Visible = $true',
    '$n.ShowBalloonTip(15000)',
    'Start-Sleep -Seconds 20',
    '$n.Dispose()',
  ].join('\n');
  try {
    const encoded = Buffer.from(script, 'utf16le').toString('base64');
    const child = spawn('powershell.exe',
      ['-NoProfile', '-NonInteractive', '-WindowStyle', 'Hidden', '-EncodedCommand', encoded],
      { detached: true, stdio: 'ignore', windowsHide: true });
    child.on('error', () => {});
    child.unref();
    return true;
  } catch {
    return false;
  }
}

// ------------------------------------------------------------------- health

function siblingPath(configPath, suffix) {
  return configPath.endsWith('.json')
    ? configPath.replace(/\.json$/, suffix)
    : configPath + suffix;
}

function readJson(file) {
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return null; }
}

function keyOf(a) { return `${a.provider || 'anthropic'}:${a.name}`; }

export class AuthHealth {
  /**
   * @param accountManager  anything with an `accounts` array (name, provider,
   *   type, status, disabled, refreshToken, _deadRefreshToken, refreshTokenExpiresAt)
   * @param opts.configPath  teamclaude.json path; the two files sit beside it
   */
  constructor(accountManager, { configPath, notify = windowsNotify, now = () => Date.now(), warnDays = 3, remindMs = 6 * HOUR, intervalMs = 60_000 } = {}) {
    this.am = accountManager;
    this.file = siblingPath(configPath, '.auth-health.json');
    this.eventsFile = siblingPath(configPath, '.auth-events.jsonl');
    this.notify = notify;
    this.now = now;
    this.warnMs = warnDays * DAY;
    this.remindMs = remindMs;
    this.intervalMs = intervalMs;
    this.timer = null;
    // Carry history across restarts (last good refresh, last failure, when we
    // last alerted) so a restart neither forgets evidence nor re-alerts at once.
    this.records = new Map();
    const prev = readJson(this.file);
    for (const r of prev?.accounts || []) {
      if (r && r.name) this.records.set(`${r.provider || 'anthropic'}:${r.name}`, { ...r });
    }
  }

  rec(a) {
    const k = keyOf(a);
    let r = this.records.get(k);
    if (!r) {
      r = { name: a.name, provider: a.provider || 'anthropic', state: null, since: null, lastOkAt: null, lastFail: null, notifiedAt: null, expiryNotifiedAt: null };
      this.records.set(k, r);
    }
    return r;
  }

  stateOf(a) {
    if (a.type !== 'oauth') return 'n/a';
    if (a.disabled) return 'disabled';
    if (a.status === 'error' || (a._deadRefreshToken && a._deadRefreshToken === a.refreshToken)) return 'needs-login';
    const exp = Number(a.refreshTokenExpiresAt) || null;
    if (exp && exp - this.now() <= this.warnMs) return 'expiring';
    return 'ok';
  }

  /** Called by ensureTokenFresh after a successful refresh. */
  refreshOk(account) {
    const r = this.rec(account);
    r.lastOkAt = new Date(this.now()).toISOString();
    if (account.refreshTokenExpiresAt) r.refreshTokenExpiresAt = new Date(Number(account.refreshTokenExpiresAt)).toISOString();
    this.event({ type: 'refresh-ok', account: account.name, provider: r.provider, refreshTokenExpiresAt: r.refreshTokenExpiresAt || null });
    this.check();
  }

  /** Called by ensureTokenFresh after a failed refresh (any kind). */
  refreshFailed(account, err) {
    const r = this.rec(account);
    const kind = classifyRefreshError(err);
    const prevFail = r.lastFail;
    // A rejection right after a network failure on the same account is the
    // "rotation lost in transit" signature: upstream may have rotated the
    // token while the reply never arrived.
    const afterNetwork = kind !== 'network' && kind !== 'server' && prevFail?.kind === 'network'
      && this.now() - Date.parse(prevFail.at) < DAY;
    r.lastFail = { at: new Date(this.now()).toISOString(), kind, status: err?.status ?? null, reason: safeReason(err), ...(afterNetwork && { afterNetwork: true }) };
    this.event({ type: 'refresh-failed', account: account.name, provider: r.provider, ...r.lastFail });
    this.check();
  }

  /** Per-account view for the status API. */
  describe(a) {
    const r = this.records.get(keyOf(a));
    const exp = Number(a.refreshTokenExpiresAt) || (r?.refreshTokenExpiresAt ? Date.parse(r.refreshTokenExpiresAt) : null);
    return {
      state: this.stateOf(a),
      since: r?.since || null,
      lastOkAt: r?.lastOkAt || null,
      lastFail: r?.lastFail || null,
      refreshTokenExpiresAt: exp ? new Date(exp).toISOString() : null,
      daysLeft: exp ? Math.floor((exp - this.now()) / DAY) : null,
    };
  }

  /** Recompute every account's state, alert on transitions, write the snapshot. */
  check() {
    const now = this.now();
    const newlyDown = [];
    const expiring = [];
    for (const a of this.am.accounts || []) {
      if (a.type !== 'oauth') continue;
      const r = this.rec(a);
      const state = this.stateOf(a);
      if (a.refreshTokenExpiresAt) r.refreshTokenExpiresAt = new Date(Number(a.refreshTokenExpiresAt)).toISOString();
      if (state !== r.state) {
        if (r.state !== null || state === 'needs-login') {
          this.event({ type: 'state', account: a.name, provider: r.provider, from: r.state, to: state });
        }
        if (state === 'needs-login') {
          console.error(`[TeamClaude] AUTH: account "${a.name}" needs re-login (${r.lastFail?.kind || 'rejected'}) — rotation is now one account smaller`);
        } else if (r.state === 'needs-login') {
          console.log(`[TeamClaude] AUTH: account "${a.name}" is back (${state})`);
          r.notifiedAt = null;
        }
        r.state = state;
        r.since = new Date(now).toISOString();
      }
      if (state === 'needs-login' && (!r.notifiedAt || now - Date.parse(r.notifiedAt) >= this.remindMs)) {
        newlyDown.push(r);
      }
      if (state === 'expiring' && (!r.expiryNotifiedAt || now - Date.parse(r.expiryNotifiedAt) >= DAY)) {
        expiring.push({ r, a });
      }
    }
    if (newlyDown.length) {
      const names = newlyDown.map(r => r.name.split('@')[0]).join(', ');
      const kinds = [...new Set(newlyDown.map(r => KIND_KO[r.lastFail?.kind] || KIND_KO.rejected))].join(' / ');
      const sent = this.notify('IRIS 중계기: 재로그인 필요',
        `${names} 계정이 순환에서 빠졌습니다(${kinds}). 대시보드의 계정 추가 단추로 같은 계정에 다시 로그인하세요. 중계기 계정은 데스크톱 앱이나 다른 PC에서 로그인하지 마세요.`);
      for (const r of newlyDown) r.notifiedAt = new Date(now).toISOString();
      this.event({ type: 'alert', alert: 'needs-login', accounts: newlyDown.map(r => r.name), shown: !!sent });
    }
    if (expiring.length) {
      const parts = expiring.map(({ a }) => {
        const exp = Number(a.refreshTokenExpiresAt);
        const d = new Date(exp);
        return `${a.name.split('@')[0]} ${Math.max(0, Math.floor((exp - now) / DAY))}일 뒤(${d.getMonth() + 1}/${d.getDate()})`;
      }).join(', ');
      const sent = this.notify('IRIS 중계기: 로그인 만료 임박',
        `${parts} 로그인이 만료됩니다. 미리 대시보드의 계정 추가 단추로 같은 계정에 다시 로그인하세요.`);
      for (const { r } of expiring) r.expiryNotifiedAt = new Date(now).toISOString();
      this.event({ type: 'alert', alert: 'expiring', accounts: expiring.map(({ a }) => a.name), shown: !!sent });
    }
    this.write();
  }

  snapshot() {
    const accounts = [...this.records.values()].filter(r =>
      (this.am.accounts || []).some(a => a.type === 'oauth' && keyOf(a) === `${r.provider}:${r.name}`));
    const count = s => accounts.filter(r => r.state === s).length;
    return {
      updatedAt: new Date(this.now()).toISOString(),
      pid: process.pid,
      summary: { needsLogin: count('needs-login'), expiring: count('expiring'), ok: count('ok') },
      accounts,
    };
  }

  write() {
    try {
      const tmp = `${this.file}.${process.pid}.tmp`;
      fs.writeFileSync(tmp, JSON.stringify(this.snapshot(), null, 2));
      fs.renameSync(tmp, this.file);
    } catch (err) {
      console.error(`[TeamClaude] AUTH: could not write health file: ${err.message}`);
    }
  }

  event(obj) {
    try {
      try {
        if (fs.statSync(this.eventsFile).size > 1_000_000) fs.renameSync(this.eventsFile, `${this.eventsFile}.1`);
      } catch { /* no file yet */ }
      fs.appendFileSync(this.eventsFile, JSON.stringify({ t: new Date(this.now()).toISOString(), ...obj }) + '\n');
    } catch { /* history is best-effort */ }
  }

  start() {
    sink = this;
    this.event({ type: 'start', pid: process.pid });
    setTimeout(() => this.check(), 5_000).unref?.();
    this.timer = setInterval(() => this.check(), this.intervalMs);
    this.timer.unref?.();
    return this;
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
    if (sink === this) sink = null;
  }
}

/** Wire-up used by serverCommand. */
export function startAuthHealth(accountManager, opts) {
  stampConsole();
  return new AuthHealth(accountManager, opts).start();
}

// (local patch 2026-10-02 IRIS) tests for src/auth-health.js and the exhausted-message split.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { AuthHealth, classifyRefreshError, safeReason, stamp } from './src/auth-health.js';
import { exhaustedMessage } from './src/server.js';

const DAY = 86_400_000;

function tmpConfig() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'tc-auth-'));
  return { dir, configPath: path.join(dir, 'teamclaude.json') };
}
function acct(name, extra = {}) {
  return { name, provider: 'anthropic', type: 'oauth', status: 'active', disabled: false, refreshToken: 'rt-' + name, ...extra };
}
function rejected(body) {
  const e = new Error(`Token refresh failed (400): ${body}`);
  e.status = 400;
  return e;
}

test('classifyRefreshError separates expired / invalid / server / network', () => {
  assert.equal(classifyRefreshError(rejected('{"error":"invalid_grant","error_description":"Refresh token expired"}')), 'expired');
  assert.equal(classifyRefreshError(rejected('{"error":"invalid_grant","error_description":"Refresh token not found or invalid"}')), 'invalid');
  assert.equal(classifyRefreshError(Object.assign(new Error('x'), { status: 403 })), 'rejected');
  assert.equal(classifyRefreshError(Object.assign(new Error('x'), { status: 502 })), 'server');
  assert.equal(classifyRefreshError(new TypeError('fetch failed')), 'network');
});

test('safeReason keeps the error code/description and never echoes long token-like strings', () => {
  assert.equal(safeReason(rejected('{"error":"invalid_grant","error_description":"Refresh token expired"}')), 'invalid_grant: Refresh token expired');
  const leaked = safeReason(new Error('bad sk-ant-ort01-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA thing'));
  assert.ok(!leaked.includes('AAAAAAAAAAAAAAAAAAAAAAAA'), leaked);
});

test('stamp formats MM-DD HH:MM:SS', () => {
  assert.equal(stamp(new Date(2026, 9, 2, 7, 5, 9)), '10-02 07:05:09');
});

test('a rejected refresh -> needs-login, one alert, health file + event log written, no token in files', () => {
  const { configPath } = tmpConfig();
  const a = acct('user3@example.test');
  const b = acct('user0@example.test');
  const am = { accounts: [a, b] };
  const alerts = [];
  let now = Date.UTC(2026, 9, 2, 7, 0, 0);
  const h = new AuthHealth(am, { configPath, notify: (t, body) => { alerts.push([t, body]); return true; }, now: () => now });
  h.check();
  assert.equal(alerts.length, 0);

  // what ensureTokenFresh does on an auth rejection, then reports
  a.status = 'error';
  a._deadRefreshToken = a.refreshToken;
  h.refreshFailed(a, rejected('{"error":"invalid_grant","error_description":"Refresh token not found or invalid"}'));
  assert.equal(alerts.length, 1);
  assert.match(alerts[0][1], /user3/);
  assert.match(alerts[0][1], /다시 로그인/);

  const snap = JSON.parse(fs.readFileSync(configPath.replace(/\.json$/, '.auth-health.json'), 'utf8'));
  assert.equal(snap.summary.needsLogin, 1);
  assert.equal(snap.summary.ok, 1);
  const rec = snap.accounts.find(r => r.name === 'user3@example.test');
  assert.equal(rec.state, 'needs-login');
  assert.equal(rec.lastFail.kind, 'invalid');

  const events = fs.readFileSync(configPath.replace(/\.json$/, '.auth-events.jsonl'), 'utf8');
  assert.match(events, /refresh-failed/);
  assert.match(events, /"alert":"needs-login"/);
  for (const text of [JSON.stringify(snap), events]) assert.ok(!text.includes('rt-user'), 'token value leaked');

  // still down: no repeat inside the reminder window, one reminder after it
  now += 60_000; h.check();
  assert.equal(alerts.length, 1);
  now += 6 * 3_600_000; h.check();
  assert.equal(alerts.length, 2);

  // re-login: new refresh token, status back to active -> recovered, no alert
  a.refreshToken = 'rt-new'; a.status = 'active';
  now += 60_000; h.check();
  assert.equal(alerts.length, 2);
  assert.equal(h.describe(a).state, 'ok');
  assert.match(fs.readFileSync(configPath.replace(/\.json$/, '.auth-events.jsonl'), 'utf8'), /"from":"needs-login","to":"ok"/);
});

