// 429 black box (local patch 2026-10-03 IRIS).
//
// Why: a subscription (OAuth) token refuses an Opus/Sonnet request that does
// not look like Claude Code with a 429 that carries NO unified quota headers —
// on every account alike. The proxy read that as a per-minute throttle, paused
// the account, hopped to an idle sibling (which refused it too), then waited
// 60s per retry. One such client kept two accounts paused for hours, and the
// idle account it always landed on looked broken (2026-10-02: 46/46 refused on
// a healthy account). Upstream discards the 429 body and the request log skips
// a pure 429-then-retry, so nothing said which program sent it.
//
// This module records every upstream 429 as one JSON line next to the config
// (`teamclaude.reject-events.jsonl`, rotated at 1 MB): account, model, the
// quota-header verdict, Anthropic's own error text, and who sent it — the
// client's user-agent / x-app / beta header, whether the system prompt carries
// the Claude Code identity, and (Windows) the owning process of the client's
// socket. Never the message content and never a token.

import fs from 'node:fs';
import { spawn } from 'node:child_process';
import { getConfigPath } from './config.js';

const MAX_FILE = 1_000_000;
const PID_LOOKUP_GAP_MS = 20_000;
// Markers a Claude Code / Agent SDK system prompt starts with. Searched in the
// raw body bytes, so no JSON parse of a multi-megabyte context is needed.
const CC_MARKERS = [
  "You are Claude Code, Anthropic's official CLI for Claude",
  "You are a Claude agent, built on Anthropic's Claude Agent SDK",
];

let fileOverride = null;
let seq = 0;
let lastPidLookup = 0;
const pidByPort = new Map();

/** Tests point the log elsewhere; null restores the default. */
export function setRejectLogFile(file) { fileOverride = file; }

export function rejectLogFile() {
  if (fileOverride) return fileOverride;
  const cfg = getConfigPath();
  return cfg.endsWith('.json') ? cfg.replace(/\.json$/, '.reject-events.jsonl') : `${cfg}.reject-events.jsonl`;
}

function clip(v, n) {
  if (v == null) return null;
  // Control characters out (log-line safety), then cap.
  const s = String(v).replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
  return s.length > n ? `${s.slice(0, n)}…` : s;
}

/** True when any unified (subscription quota) header came back. */
export function hasUnifiedHeaders(rl) {
  return Object.keys(rl || {}).some(k => k.startsWith('anthropic-ratelimit-unified'));
}

/** The quota-status headers only (values are short words like allowed/rejected). */
export function unifiedStatuses(rl) {
  const out = {};
  for (const [k, v] of Object.entries(rl || {})) {
    if (k.startsWith('anthropic-ratelimit-unified') && k.endsWith('status')) {
      out[k.slice('anthropic-ratelimit-unified-'.length) || 'status'] = clip(v, 40);
    }
  }
  return out;
}

/** Which identity, if any, the request's system prompt opens with. */
export function identityOf(body) {
  if (!body || !body.length) return null;
  const buf = Buffer.isBuffer(body) ? body : Buffer.from(String(body));
  for (const m of CC_MARKERS) {
    // The marker may sit inside a JSON string, where ' stays as-is.
    if (buf.indexOf(m) !== -1) return m.startsWith('You are Claude Code') ? 'claude-code' : 'agent-sdk';
  }
  return 'none';
}

/** Short summary of who sent the request — headers only, no content. */
export function describeClient(req, body) {
  const h = req?.headers || {};
  return {
    ua: clip(h['user-agent'], 120),
    app: clip(h['x-app'], 40),
    beta: clip(h['anthropic-beta'], 200),
    identity: identityOf(body),
    bodyBytes: body?.length ?? 0,
    port: req?.socket?.remotePort ?? null,
  };
}

/** Anthropic's own error text out of a 429 body (JSON or plain). */
export function upstreamError(text) {
  if (!text) return null;
  try {
    const j = JSON.parse(text);
    const e = j?.error || j;
    return { type: clip(e?.type, 60), message: clip(e?.message ?? text, 300) };
  } catch {
    return { type: null, message: clip(text, 300) };
  }
}

/** Read at most `cap` bytes of a fetch Response body as text; never throws. */
export async function readCapped(res, cap = 8192) {
  try {
    const reader = res.body?.getReader?.();
    if (!reader) return '';
    const parts = [];
    let n = 0;
    while (n < cap) {
      const { done, value } = await reader.read();
      if (done) break;
      parts.push(Buffer.from(value));
      n += value.length;
    }
    try { await reader.cancel(); } catch { /* already closed */ }
    return Buffer.concat(parts).subarray(0, cap).toString('utf8');
  } catch {
    try { await res.body?.cancel(); } catch { /* ignore */ }
    return '';
  }
}

function append(obj) {
  const file = rejectLogFile();
  try {
    try {
      if (fs.statSync(file).size > MAX_FILE) fs.renameSync(file, `${file}.1`);
    } catch { /* no file yet */ }
    fs.appendFileSync(file, JSON.stringify({ t: new Date().toISOString(), ...obj }) + '\n');
  } catch { /* the black box is best-effort, never breaks a request */ }
}

/**
 * Record one upstream 429. Returns the event id so a later decision line can
 * point back at it. `lookupPid` (default: Windows only) adds a follow-up
 * {type:'client'} line naming the process that owns the client's socket.
 */
export function noteReject(fields, { lookupPid = process.platform === 'win32' && process.env.TEAMCLAUDE_REJECT_PID !== '0' } = {}) {
  const id = `${process.pid}-${++seq}`;
  append({ type: '429', id, ...fields });
  const port = fields?.client?.port;
  if (lookupPid && port) clientProcess(port, id);
  return id;
}

/** Record the proxy's decision about a 429 (e.g. request-specific passthrough). */
export function noteDecision(fields) { append({ type: 'decision', ...fields }); }

function clientProcess(port, ref) {
  const known = pidByPort.get(port);
  if (known) { append({ type: 'client', ref, ...known, cached: true }); return; }
  const now = Date.now();
  if (now - lastPidLookup < PID_LOOKUP_GAP_MS) return;
  lastPidLookup = now;
  // The client's socket: its LOCAL port is our remotePort, its remote port is
  // the proxy's listen port. One hidden PowerShell, JSON out, parsed here.
  const script = [
    '$ErrorActionPreference = "SilentlyContinue"',
    `$c = Get-NetTCPConnection -LocalPort ${Number(port)} | Where-Object { $_.OwningProcess -ne $PID } | Select-Object -First 1`,
    'if (-not $c) { "{}"; exit }',
    '$p = Get-CimInstance Win32_Process -Filter "ProcessId=$($c.OwningProcess)"',
    '$q = Get-CimInstance Win32_Process -Filter "ProcessId=$($p.ParentProcessId)"',
    '@{ pid = $p.ProcessId; name = $p.Name; cmd = $p.CommandLine; parentPid = $q.ProcessId; parentName = $q.Name; parentCmd = $q.CommandLine } | ConvertTo-Json -Compress',
  ].join('\n');
  try {
    const child = spawn('powershell.exe',
      ['-NoProfile', '-NonInteractive', '-WindowStyle', 'Hidden', '-EncodedCommand', Buffer.from(script, 'utf16le').toString('base64')],
      { stdio: ['ignore', 'pipe', 'ignore'], windowsHide: true });
    let out = '';
    child.stdout.on('data', d => { out += d; });
    child.on('error', () => {});
    child.on('close', () => {
      let j = {};
      try { j = JSON.parse(out.trim() || '{}'); } catch { /* ignore */ }
      if (!j.pid) { append({ type: 'client', ref, port, found: false }); return; }
      const info = {
        port, pid: j.pid, name: clip(j.name, 60), cmd: clip(j.cmd, 300),
        parentPid: j.parentPid ?? null, parentName: clip(j.parentName, 60), parentCmd: clip(j.parentCmd, 200),
      };
      pidByPort.set(port, info);
      if (pidByPort.size > 200) pidByPort.delete(pidByPort.keys().next().value);
      append({ type: 'client', ref, ...info });
    });
  } catch { /* best-effort */ }
}

// 429 black box + request-specific passthrough (local patch 2026-10-03 IRIS).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  setRejectLogFile, identityOf, describeClient, upstreamError, hasUnifiedHeaders, unifiedStatuses, noteReject,
} from './src/reject-log.js';
import { AccountManager } from './src/account-manager.js';
import { createProxyRequestListener } from './src/server.js';

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'tc-reject-'));
const logFile = path.join(tmp, 'reject.jsonl');
setRejectLogFile(logFile);
const readLog = () => (fs.existsSync(logFile) ? fs.readFileSync(logFile, 'utf8').trim().split('\n').filter(Boolean).map(l => JSON.parse(l)) : []);
const resetLog = () => { try { fs.unlinkSync(logFile); } catch { /* none */ } };

const CC = "You are Claude Code, Anthropic's official CLI for Claude.";
const body = (system) => Buffer.from(JSON.stringify({
  model: 'claude-opus-5-5', max_tokens: 1,
  ...(system ? { system: [{ type: 'text', text: system }] } : {}),
  messages: [{ role: 'user', content: 'secret user words' }],
}));

test('helpers: identity, client summary, error text, quota headers', () => {
  assert.equal(identityOf(body(CC)), 'claude-code');
  assert.equal(identityOf(body("You are a Claude agent, built on Anthropic's Claude Agent SDK.")), 'agent-sdk');
  assert.equal(identityOf(body('You are a helpful bot')), 'none');
  assert.equal(identityOf(Buffer.alloc(0)), null);
  const c = describeClient({ headers: { 'user-agent': 'claude-cli/9 (external, cli)\n', 'x-app': 'cli' }, socket: { remotePort: 5555 } }, body(null));
  assert.equal(c.ua, 'claude-cli/9 (external, cli)');
  assert.equal(c.identity, 'none');
  assert.equal(c.port, 5555);
  assert.ok(!JSON.stringify(c).includes('secret user words'), 'no message content');
  assert.deepEqual(upstreamError('{"type":"error","error":{"type":"rate_limit_error","message":"Nope"}}'), { type: 'rate_limit_error', message: 'Nope' });
  assert.equal(upstreamError('plain text').message, 'plain text');
  assert.equal(upstreamError(''), null);
  assert.equal(hasUnifiedHeaders({ 'anthropic-ratelimit-unified-5h-status': 'allowed' }), true);
  assert.equal(hasUnifiedHeaders({}), false);
  assert.deepEqual(unifiedStatuses({ 'anthropic-ratelimit-unified-5h-status': 'allowed', 'anthropic-ratelimit-unified-5h-utilization': '0.1' }), { '5h-status': 'allowed' });
});

test('noteReject writes one line, no pid lookup when disabled, rotates past 1 MB', () => {
  resetLog();
  noteReject({ account: 'a', client: { port: 1 } }, { lookupPid: false });
  const lines = readLog();
  assert.equal(lines.length, 1);
  assert.equal(lines[0].type, '429');
  assert.equal(lines[0].account, 'a');
  fs.writeFileSync(logFile, 'x'.repeat(1_000_001));
  noteReject({ account: 'b' }, { lookupPid: false });
  assert.ok(fs.existsSync(`${logFile}.1`));
  assert.equal(readLog().length, 1);
  resetLog();
});

// ---- integration: fake upstream + real proxy listener ----

function fakeUpstream(handler) {
  return new Promise(resolve => {
    const hits = [];
    const srv = http.createServer((req, res) => {
      const chunks = [];
      req.on('data', c => chunks.push(c));
      req.on('end', () => { const b = Buffer.concat(chunks); hits.push({ auth: req.headers.authorization, body: b.toString() }); handler(req, res, b); });
    });
    srv.listen(0, '127.0.0.1', () => resolve({ srv, hits, url: `http://127.0.0.1:${srv.address().port}` }));
  });
}

function proxyFor(upstreamUrl) {
  const far = Date.now() + 24 * 3600 * 1000;
  const am = new AccountManager([
    { name: 'acct-a', type: 'oauth', accessToken: 'tok-a', refreshToken: 'r-a', expiresAt: far },
    { name: 'acct-b', type: 'oauth', accessToken: 'tok-b', refreshToken: 'r-b', expiresAt: far },
  ], 1);
  const listener = createProxyRequestListener({ accountManager: am, upstream: upstreamUrl, config: {} });
  return new Promise(resolve => {
    const srv = http.createServer(listener);
    srv.listen(0, '127.0.0.1', () => resolve({ srv, am, url: `http://127.0.0.1:${srv.address().port}` }));
  });
}

function send(url, b) {
  return new Promise((resolve, reject) => {
    const t0 = Date.now();
    const req = http.request(`${url}/v1/messages`, { method: 'POST', headers: { 'content-type': 'application/json', 'anthropic-version': '2023-06-01', 'user-agent': 'test-client/1' } }, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, text: Buffer.concat(chunks).toString(), ms: Date.now() - t0 }));
    });
    req.on('error', reject);
    req.end(b);
  });
}

const REFUSE = JSON.stringify({ type: 'error', error: { type: 'rate_limit_error', message: 'Refused: not Claude Code' } });

test('request refused on two accounts without quota headers → Anthropic 429 passed through at once, nobody stays paused', async () => {
  resetLog();
  const up = await fakeUpstream((req, res, b) => {
    if (!b.includes(CC)) { res.writeHead(429, { 'content-type': 'application/json', 'request-id': 'req_x' }); res.end(REFUSE); return; }
    res.writeHead(200, { 'content-type': 'application/json' }); res.end('{"type":"message"}');
  });
  const px = await proxyFor(up.url);
  try {
    const r = await send(px.url, body(null));
    assert.equal(r.status, 429);
    assert.ok(r.text.includes('Refused: not Claude Code'), 'client sees the real reason');
    assert.equal(r.headers['request-id'], 'req_x');
    assert.ok(r.ms < 10_000, `answered in ${r.ms} ms, no 60 s wait`);
    assert.equal(up.hits.length, 2, 'tried exactly two accounts');
    assert.notEqual(up.hits[0].auth, up.hits[1].auth);
    assert.equal(px.am.isPaused(0), false);
    assert.equal(px.am.isPaused(1), false);
    const log = readLog();
    assert.equal(log.filter(e => e.type === '429').length, 2);
    const d = log.find(e => e.type === 'decision');
    assert.equal(d?.decision, 'request-specific');
    assert.equal(log[0].client.identity, 'none');
    assert.equal(log[0].client.ua, 'test-client/1');
    assert.equal(log[0].error.message, 'Refused: not Claude Code');
    assert.ok(!fs.readFileSync(logFile, 'utf8').includes('secret user words'));
    assert.ok(!fs.readFileSync(logFile, 'utf8').includes('tok-'));
    // A well-formed request right after is served normally.
    const ok = await send(px.url, body(CC));
    assert.equal(ok.status, 200);
  } finally { px.srv.close(); up.srv.close(); }
});

test('429 WITH quota headers keeps the old path (pause + retry, no passthrough decision)', async () => {
  resetLog();
  let n = 0;
  const up = await fakeUpstream((req, res) => {
    n++;
    if (n <= 2) {
      res.writeHead(429, { 'content-type': 'application/json', 'retry-after': '1', 'anthropic-ratelimit-unified-5h-status': 'allowed' });
      res.end(REFUSE); return;
    }
    res.writeHead(200, { 'content-type': 'application/json' }); res.end('{"type":"message"}');
  });
  const px = await proxyFor(up.url);
  try {
    const r = await send(px.url, body(CC));
    assert.equal(r.status, 200, 'retried and served');
    const log = readLog();
    assert.equal(log.filter(e => e.type === '429').length, 2);
    assert.equal(log.filter(e => e.type === 'decision').length, 0);
    assert.equal(log[0].noQuotaHeaders, false);
  } finally { px.srv.close(); up.srv.close(); }
});
